for(let i=0;i<100;i++){let x=rand()*240-120,z=rand()*240-120;if(Math.abs(x)<26&&z>-30&&z<30)continue;if(x>20&&x<65&&z>-8&&z<48)continue;tree(x,z,.6+rand()*.8);}
