// A patched coat and straw hat mark the player as a village farmhand.
function person(x,z,color='#756749',scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);const legs=[new THREE.Object3D(),new THREE.Object3D()],arms=[new THREE.Object3D(),new THREE.Object3D()];return {g,legs,arms};}
const player=person(0,18);player.g.rotation.y=Math.PI;const sword=box(.1,.95,.08,'#b6b6a0',0,-.5,.25,player.arms[1]);sword.rotation.x=-.5;const wen=person(-6,-1,'#6c7272');
let playing=false,paused=false,stamina=100,hp=100,copper=0,remedies=3,attack=0,dodge=0,healTimer=0,toastTimer=0,talked=false;const keys=new Set();const defeated=new Set();
const bosses=[];function boss(name,x,z,color,scale,hp,reward){let p=person(x,z,color,scale);let b={...p,name,x,z,home:new THREE.Vector3(x,0,z),max:hp,hp,state:'idle',timer:0,reward,hit:false};bosses.push(b);const ring=new THREE.Mesh(new THREE.RingGeometry(2.7*scale,2.85*scale,48),new THREE.MeshBasicMaterial({color:'#b97743',transparent:true,opacity:.55,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.05,z);scene.add(ring);b.ring=ring;}
boss('The Tribute Collector',-42,44,'#655045',1.5,150,20);boss('The Reed Marsh Guardian',66,43,'#5a6b4b',2.1,220,30);boss('The Mountain Warden',10,-77,'#4d5c62',2.5,320,50);
for(let b of bosses){let arena=cyl(11,11,.04,'#8b8967',b.x,.005,b.z,scene,40);}
const herbs=[];for(let i=0;i<16;i++){let x=rand()*150-75,z=rand()*140-60;const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);for(let n=0;n<3;n++){let leaf=ball(.28,'#c6aa6f',n*.18-.2,.6+n*.15,0,g);leaf.scale.set(.5,1.8,.5);}herbs.push(g);}
function save(){try{localStorage.setItem('dust-rice-v1',JSON.stringify({copper,remedies,defeated:[...defeated],talked}));}catch{}}
try{const s=JSON.parse(localStorage.getItem('dust-rice-v1'));if(s){copper=s.copper??0;remedies=s.remedies??3;talked=!!s.talked;for(let name of s.defeated??[])defeated.add(name);for(let b of bosses)if(defeated.has(b.name)){b.hp=0;b.g.visible=false;b.ring.visible=false;}}}catch{}
function toast(msg){$('toast').textContent=msg;toastTimer=3;$('toast').style.opacity=1;}
function dialog(title,text){paused=true;controls.release();keys.clear();$('speaker').textContent='VILLAGE ELDER WEN';$('dialogTitle').textContent=title;$('dialogText').textContent=text;$('dialog').hidden=false;}
function interact(){if(player.g.position.distanceTo(wen.g.position)<5){talked=true;save();if(defeated.size===3){dialog('The harvest is ours.','No collector at the gate. No fear on the mountain road. There is still work to do, Lin—but tonight, we eat together. You have completed the valley’s first chapter.');}else if(copper>=10){copper-=10;remedies+=2;hp=100;save();dialog('A little warmth for the road.','Ten copper will buy herbs enough for two remedies. Rest here a moment. Your strength has returned.');}else{hp=100;remedies=Math.max(remedies,3);save();dialog('We cannot pay another tribute.','The collector camps southwest. A restless guardian stalks the rice marsh to the east, and the mountain warden blocks the northern road. Watch for the red circle before a heavy blow. Dodge away, then strike. Gather golden herbs for remedies. Return here to rest; ten copper buys two remedies.');}}else{const herb=herbs.find(g=>g.visible&&g.position.distanceTo(player.g.position)<3);if(herb){herb.visible=false;remedies++;save();toast('Medicinal herbs gathered · +1 remedy');}}}
function strike(){if(!playing||paused||attack>0||stamina<15)return;attack=.42;stamina-=15;let nearest=bosses.filter(b=>b.hp>0&&b.g.position.distanceTo(player.g.position)<4.5).sort((a,b)=>a.g.position.distanceTo(player.g.position)-b.g.position.distanceTo(player.g.position))[0];if(nearest){player.g.rotation.y=Math.atan2(nearest.g.position.x-player.g.position.x,nearest.g.position.z-player.g.position.z);nearest.hp=Math.max(0,nearest.hp-22);toast('22 · hit');if(nearest.hp===0){defeated.add(nearest.name);nearest.g.visible=false;nearest.ring.visible=false;copper+=nearest.reward;save();toast(nearest.name+' defeated · +'+nearest.reward+' copper');}}}
$('start').onclick=()=>{playing=true;paused=false;$('menu').hidden=true;$('start').textContent='Return to the valley →';controls.capture();};$('pause').onclick=()=>{if(!playing)return;paused=!paused;$('menu').hidden=!paused;keys.clear();if(paused)controls.release();else controls.capture();};$('closeDialog').onclick=()=>{$('dialog').hidden=true;paused=false;};$('reset').onclick=()=>{if(confirm('Erase saved progress and begin again?')){localStorage.removeItem('dust-rice-v1');location.reload();}};
addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Escape'){if(!paused)$('pause').click();return;}if(!playing||paused)return;if(e.code==='KeyC'){controls.toggle();return;}if(e.code==='KeyE')interact();if(e.code==='KeyJ')strike();if(e.code==='Space'&&stamina>=25&&dodge<=0){dodge=.4;stamina-=25;}if(e.code==='KeyQ'&&remedies>0&&hp<100){remedies--;hp=Math.min(100,hp+45);save();toast('Remedy used · +45 health');}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();if(playing&&!paused)$('pause').click();});
