function hud(){ $('health').style.width=hp+'%';$('stamina').style.width=stamina+'%';$('coins').textContent=copper+' copper';$('potions').textContent=remedies+' remedies';$('progress').textContent=defeated.size+' / 3 threats defeated';if(talked){$('questTitle').textContent=defeated.size===3?'The valley breathes again':'Break the tribute';$('questText').textContent=defeated.size===3?'Return to Old Wen by the village well.':'Find the collector southwest, the guardian east, and the warden on the northern road.';}let p=player.g.position;$('location').firstChild.textContent=(p.z<-40?'THE NORTHERN ROAD':p.x>26?'THE REED MARSH':p.x<-28?'THE COLLECTOR’S CAMP':'SHUǏTIÁN VILLAGE')+' ';const ctx=$('map').getContext('2d');ctx.clearRect(0,0,180,180);ctx.fillStyle='#354334';ctx.fillRect(0,0,180,180);ctx.strokeStyle='#998e6155';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(90,10);ctx.lineTo(90,155);ctx.moveTo(40,120);ctx.lineTo(135,120);ctx.stroke();for(let o of obstacles){ctx.fillStyle='#ac9b75';ctx.fillRect(90+o.x*.65-3,90+o.z*.65-3,6,6);}for(let b of bosses){ctx.fillStyle=b.hp>0?'#d37b58':'#89976b';ctx.beginPath();ctx.arc(90+b.home.x*.65,90+b.home.z*.65,4,0,7);ctx.fill();}ctx.fillStyle='#eee1b3';ctx.beginPath();ctx.arc(90+p.x*.65,90+p.z*.65,3,0,7);ctx.fill();ctx.fillStyle='#e6dab7';ctx.font='10px Arial';ctx.fillText('N',86,15);}
