let last=0;function frame(ms){requestAnimationFrame(frame);let dt=Math.min((ms-last)/1000,.05);last=ms;const t=ms/1000;update(dt,t);const target=player.g.position.clone().add(new THREE.Vector3(0,1.5,0));const orbit=orbitOffset(controls.yaw,controls.pitch,controls.distance);const offset=new THREE.Vector3(orbit.x,orbit.y,orbit.z);if(!playing){target.set(0,1,-2);offset.set(37,23,42);}camera.position.lerp(target.clone().add(offset),1-Math.exp(-dt*5));if(playing){const ray=camera.position.clone().sub(target),length=ray.length();cameraRay.set(target,ray.normalize());cameraRay.far=length;const hit=cameraRay.intersectObjects(cameraObstacles,true)[0];if(hit)camera.position.copy(target).addScaledVector(ray,Math.max(.5,hit.distance-.35));}camera.lookAt(target);controls.sync();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').style.opacity=0;}if(worldAssets&&playing&&!paused)worldAssets.update(dt,{moving:keys.has('KeyW')||keys.has('KeyA')||keys.has('KeyS')||keys.has('KeyD'),running:keys.has('ShiftLeft'),attacking:attack>0,dodging:dodge>0,time:t});hud();renderer.render(scene,camera);}camera.position.set(37,24,40);requestAnimationFrame(frame);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
